import akHeadShot from '../assets/items/ak_head_shot.svg';
import m4Printstream from '../assets/items/m4_printstream.svg';
import awpGungnir from '../assets/items/awp_gungnir.svg';
import deaglePrintstream from '../assets/items/deagle_printstream.svg';
import glockGamma from '../assets/items/glock_gamma.svg';
import karambitGamma from '../assets/items/karambit_gamma.svg';
import m9Doppler from '../assets/items/m9_doppler.svg';
import sportVice from '../assets/items/sport_vice.svg';

const map = {
  'AK-47 | Head Shot': akHeadShot,
  'M4A1-S | Printstream': m4Printstream,
  'AWP | Gungnir': awpGungnir,
  'Desert Eagle | Printstream': deaglePrintstream,
  'Glock-18 | Gamma Doppler': glockGamma,
  'Karambit | Gamma Doppler': karambitGamma,
  'M9 Bayonet | Doppler': m9Doppler,
  'Sport Gloves | Vice': sportVice,
};

export const resolveItemImage = (item) => {
  if (!item) return '';
  return map[item.name] || item.image_url || '';
};
export default map;
